INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (12935, 'Khi KHÔNG là từ yêu thích thường xuyên của Sếp bạn', 'khi-khong-la-tu-yeu-thich-thuong-xuyen-cua-sep-ban', '		<div data-elementor-type="wp-post" data-elementor-id="12935" class="elementor elementor-12935" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-a151720 e-con-full e-flex e-con e-parent" data-id="a151720" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
				<div class="elementor-element elementor-element-10935b6 elementor-widget elementor-widget-image" data-id="10935b6" data-element_type="widget" data-widget_type="image.default">
				<div class="elementor-widget-container">
															<img loading="lazy" decoding="async" width="800" height="450" src="https://media.huynhhieutravel.com/khi-khong-la-tu-yeu-thich-cua-sep.jpg" class="attachment-large size-large wp-image-12937" alt="Khi không là từ yêu thích của sếp" srcset="https://media.huynhhieutravel.com/khi-khong-la-tu-yeu-thich-cua-sep.jpg 1280w, https://media.huynhhieutravel.com/khi-khong-la-tu-yeu-thich-cua-sep-768x432.jpg 768w" sizes="(max-width: 800px) 100vw, 800px" />															</div>
				</div>
		<div class="elementor-element elementor-element-d3820cc e-flex e-con-boxed e-con e-child" data-id="d3820cc" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-95ad18a e-flex e-con-boxed e-con e-child" data-id="95ad18a" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-f9e1917 elementor-widget elementor-widget-heading" data-id="f9e1917" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h1 class="elementor-heading-title elementor-size-default">Khi KHÔNG là từ yêu thích thường xuyên của Sếp bạn</h1>				</div>
				</div>
				<div class="elementor-element elementor-element-8ba337c elementor-widget elementor-widget-text-editor" data-id="8ba337c" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
									<p>Bạn có những ý tưởng tuyệt vời. Bạn trình bày nó lên người quản lý. Và nó luôn luôn là câu trả lời KHÔNG! Đã đến lúc thay đổi chiến lược, để nhận được các kết quả tốt hơn.</p>								</div>
				</div>
					</div>
				</div>
					</div>
				</div>
				</div>
		<div class="elementor-element elementor-element-c190e3e e-flex e-con-boxed e-con e-parent" data-id="c190e3e" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-26c52cb elementor-widget-divider--view-line elementor-widget elementor-widget-divider" data-id="26c52cb" data-element_type="widget" data-widget_type="divider.default">
				<div class="elementor-widget-container">
							<div class="elementor-divider">
			<span class="elementor-divider-separator">
						</span>
		</div>
						</div>
				</div>
				<div class="elementor-element elementor-element-5c53597 elementor-widget elementor-widget-jet-breadcrumbs" data-id="5c53597" data-element_type="widget" data-widget_type="jet-breadcrumbs.default">
				<div class="elementor-widget-container">
					<div class="elementor-jet-breadcrumbs jet-blocks">
		<div class="jet-breadcrumbs">
		<div class="jet-breadcrumbs__content">
		<div class="jet-breadcrumbs__wrap"><div class="jet-breadcrumbs__item"><a href="https://huynhhieutravel.com/" class="jet-breadcrumbs__item-link is-home" rel="home" title="Home">Home</a></div>
		</div>
		</div>
		</div></div>				</div>
				</div>
				<div class="elementor-element elementor-element-e99dab2 elementor-share-buttons--view-icon elementor-share-buttons--skin-minimal elementor-share-buttons--color-custom elementor-share-buttons--shape-square elementor-grid-0 elementor-widget elementor-widget-share-buttons" data-id="e99dab2" data-element_type="widget" data-widget_type="share-buttons.default">
				<div class="elementor-widget-container">
							<div class="elementor-grid">
								<div class="elementor-grid-item">
						<div
							class="elementor-share-btn elementor-share-btn_facebook"
							role="button"
							tabindex="0"
							aria-label="Share on facebook"
						>
															<span class="elementor-share-btn__icon">
								<i class="fab fa-facebook" aria-hidden="true"></i>							</span>
																				</div>
					</div>
									<div class="elementor-grid-item">
						<div
							class="elementor-share-btn elementor-share-btn_twitter"
							role="button"
							tabindex="0"
							aria-label="Share on twitter"
						>
															<span class="elementor-share-btn__icon">
								<i class="fab fa-twitter" aria-hidden="true"></i>							</span>
																				</div>
					</div>
									<div class="elementor-grid-item">
						<div
							class="elementor-share-btn elementor-share-btn_linkedin"
							role="button"
							tabindex="0"
							aria-label="Share on linkedin"
						>
															<span class="elementor-share-btn__icon">
								<i class="fab fa-linkedin" aria-hidden="true"></i>							</span>
																				</div>
