INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (11317, 'Ngày 3: Nguyên mẫu (Sprint 2.0)', 'ngay-3-nguyen-mau-sprint-2-0', '		<div data-elementor-type="wp-post" data-elementor-id="11317" class="elementor elementor-11317" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-d672dca e-con-full e-flex e-con e-parent" data-id="d672dca" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-657acd2 e-con-full e-flex e-con e-child" data-id="657acd2" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-0e50cf7 e-flex e-con-boxed e-con e-child" data-id="0e50cf7" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
				<div class="elementor-element elementor-element-80bf37d elementor-widget elementor-widget-heading" data-id="80bf37d" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h2 class="elementor-heading-title elementor-size-default">Nguyên Mẫu</h2>				</div>
				</div>
					</div>
				</div>
		<div class="elementor-element elementor-element-fc3e20e e-flex e-con-boxed e-con e-child" data-id="fc3e20e" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-f5d6611 e-flex e-con-boxed e-con e-child" data-id="f5d6611" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
