INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (8518, 'Lập kế hoạch tài chính doanh nghiệp', 'lap-ke-hoach-tai-chinh-doanh-nghiep', '		<div data-elementor-type="wp-post" data-elementor-id="8518" class="elementor elementor-8518" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-3e8f2da e-con-full e-flex e-con e-parent" data-id="3e8f2da" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-8eb3ca2 e-con-full e-flex e-con e-parent" data-id="8eb3ca2" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-487109f e-con-full e-flex e-con e-parent" data-id="487109f" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
