INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (8299, 'Lập kế hoạch ứng phó sự cố', 'lap-ke-hoach-ung-pho-su-co', '		<div data-elementor-type="wp-post" data-elementor-id="8299" class="elementor elementor-8299" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-91a77cd e-con-full e-flex e-con e-parent" data-id="91a77cd" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-a9fe695 e-con-full e-flex e-con e-parent" data-id="a9fe695" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
