INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (8164, 'Giao tiếp hiệu quả', 'giao-tiep-hieu-qua', '		<div data-elementor-type="wp-post" data-elementor-id="8164" class="elementor elementor-8164" data-elementor-post-type="post">
