INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (7093, 'Education Website (Part 2)', 'education-website-part-2', '		<div data-elementor-type="wp-post" data-elementor-id="7093" class="elementor elementor-7093" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-b741f48 e-flex e-con-boxed e-con e-parent" data-id="b741f48" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
