INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (6297, 'Image Box Carousel với text bên trong', 'image-box-carousel-voi-text-ben-trong', '		<div data-elementor-type="wp-post" data-elementor-id="6297" class="elementor elementor-6297" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-fba4cbe card-carousel e-flex e-con-boxed e-con e-parent" data-id="fba4cbe" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-6f177a0 e-con-full e-flex e-con e-child" data-id="6f177a0" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
				<div class="elementor-element elementor-element-776af8e elementor-widget elementor-widget-heading" data-id="776af8e" data-element_type="widget" data-widget_type="heading.default">
				<div class="elementor-widget-container">
					<h2 class="elementor-heading-title elementor-size-default">Carousel Image Text</h2>				</div>
				</div>
				<div class="elementor-element elementor-element-e5e3e7c elementor-widget elementor-widget-text-editor" data-id="e5e3e7c" data-element_type="widget" data-widget_type="text-editor.default">
				<div class="elementor-widget-container">
